using System.Text.Json;
using GamePulse.Api.Models.Nfl;
using GamePulse.Api.Services;
int checks = 0;
void Check(bool ok, string label) { if (!ok) throw new Exception(label); Console.WriteLine($"PASS {++checks}: {label}"); }
NflStat Row(string id="p1", string game="g1", string team="A", string phase="REG", int week=1, object? stats=null) => new(2025,phase,week,game,team,team=="A"?"B":"A",JsonSerializer.SerializeToElement(stats ?? new { attempts=10,completions=5,passing_yards=100,passing_tds=1,passing_interceptions=0,carries=2,rushing_yards=-1,rushing_tds=0,rushing_fumbles_lost=0,targets=2,receptions=1,receiving_yards=10,receiving_tds=0,receiving_fumbles_lost=0}),id,id,"QB");
NflGame[] Games(NflStat[] rows, string status="final") => rows.GroupBy(r=>r.GameId).Select(g=>new NflGame(g.Key,2025,g.First().SeasonType,"REG",g.First().Week,"2025-09-01",null,"A","B",0,0,status,null)).ToArray();
NflPlayer[] Players(NflStat[] rows) => rows.Select(r=>r.PlayerId!).Distinct().Select(p=>new NflPlayer(p,p,"QB",["A","B"],null,null)).ToArray();
NflLeader[] Run(NflStat[] rows,string group="passing",string phase="REG",string metric="passing_yards",string? team=null,int minimum=0,string? position=null) => NflLeaderboards.Calculate(rows,Games(rows),Players(rows),group,phase,metric,team,position,minimum);
void Bad(Action action,string label){try{action();}catch(NflDataException e){Check(e.StatusCode is 400 or 503,label);return;}throw new Exception(label);}
var rows=new[]{Row(),Row(game:"g2",week:2,stats:new{attempts=30,completions=30,passing_yards=600,passing_tds=3,passing_interceptions=1})};
var p=Run(rows).Single();
Check(p.Totals["passing_yards"]==700,"Sum passing yards");
Check(p.Totals["attempts"]==40 && p.Totals["completions"]==35,"Component counts");
Check(p.Rates["completionPercentage"]==87.5,"Weighted completion percentage, not mean of game rates");
Check(p.Rates["yardsPerAttempt"]==17.5,"Y/A from complete component totals");
Check(p.Games==2 && p.Observations==2,"Distinct games and row coverage");
var missing=Run([Row(),Row(game:"g2",week:2,stats:new{attempts=10,passing_yards=20})]).Single();
Check(missing.Totals["passing_yards"]==120 && missing.Totals["completions"] is null,"Known fields summed, missing field stays null");
Check(missing.Rates["completionPercentage"] is null && missing.Rates["yardsPerAttempt"]==6,"Only dependent rate suppressed");
Check(missing.FieldObservations["completions"]==1 && missing.Observations==2,"Observed field count exposed");
var zero=Run([Row(stats:new{attempts=0,completions=0,passing_yards=1,passing_tds=0,passing_interceptions=0})]).Single();
Check(zero.Totals["completions"]==0 && zero.Rates["yardsPerAttempt"] is null,"Zero preserved, zero denominator not infinity");
var rushing=Run([Row()],group:"rushing",metric:"rushing_yards").Single();
Check(rushing.Totals["rushing_yards"]==-1 && rushing.Rates["yardsPerCarry"]==-.5,"Negative rushing yards preserved");
var receiving=Run([Row()],group:"receiving",metric:"receiving_yards").Single();
Check(receiving.Rates["yardsPerReception"]==10 && receiving.Rates["catchPercentage"]==50,"Receiving rates");
var traded=new[]{Row(),Row(game:"g2",team:"B",week:2)};
var combined=Run(traded).Single();Check(combined.Totals["passing_yards"]==200 && combined.TeamContributions.Length==2,"Traded player combined once and two team splits");
Check(Run(traded,team:"B").Single().Totals["passing_yards"]==100,"Team filter selects contribution only");
var phaseRows=new[]{Row(),Row(game:"post",phase:"POST",week:19)};
Check(Run(phaseRows).Single().Games==1 && Run(phaseRows,phase:"POST").Single().Games==1,"REG/POST remain separate");
Check(NflLeaderboards.Calculate(rows,Games(rows,"scheduled"),Players(rows),"passing","REG","passing_yards",null,null,0).Length==0,"Unplayed games excluded");
Check(Run(rows,minimum:41).Length==0 && Run(rows,minimum:40).Length==1,"Minimum attempts inclusive");
Check(Run(rows,position:"WR").Length==0 && Run(rows,position:"qb").Length==1,"Position filter case-insensitive");
var tied=Run([Row(),Row(id:"p2"),Row(id:"p3",stats:new{attempts=1,passing_yards=10})]);
Check(tied.Select(r=>r.Rank).SequenceEqual(new int?[]{1,1,3}),"Competition ranks 1,1,3");
Check(tied[0].PlayerId=="p1" && tied[1].PlayerId=="p2","Stable ID ordering for ties");
var incomplete=Run([Row(),Row(id:"p2",stats:new{attempts=1,passing_tds=1})]);
Check(incomplete.Last().Value is null && incomplete.Last().Rank is null,"Unknown metric included unranked at bottom");
Check(Run([Row(stats:new{attempts=0,completions=0,passing_yards=0,passing_tds=0,passing_interceptions=0})]).Length==0,"Zero-activity identities not listed");
Check(Run([Row(stats:new{attempts=1.0,completions=1.0,passing_yards=10.0})]).Single().Totals["attempts"]==1,"Integral numeric source floats accepted");
Check(Run([Row(stats:new{attempts=1.5,passing_yards=10})]).Single().Totals["attempts"] is null,"Fractional attempt is unavailable");
Check(Run([Row(stats:new{attempts=1,completions=2,passing_yards=10})]).Single().Rates["completionPercentage"] is null,"Inconsistent completion rate not invented");
Bad(()=>Run(rows,group:"defense"),"Unknown category rejected");
Bad(()=>Run(rows,phase:"ALL"),"Combined phase rejected");
Bad(()=>Run(rows,metric:"era"),"Wrong metric rejected");
Bad(()=>Run(rows,minimum:-1),"Negative minimum rejected");
Bad(()=>Run([Row(),Row()]),"Duplicate player/game/team rejected");
var unknown=Row() with{OpponentTeamId="X"};Bad(()=>Run([unknown]),"Wrong opponent rejected");
Check(NflLeaderboards.Calculate(rows,Games(rows),Players(rows).Append(new NflPlayer("roster-only","Roster only",null,[],null,null)).ToArray(),"passing","REG","passing_yards",null,null,0).Length==1,"Roster-only player not assigned appearances");
var legacyRoster=JsonSerializer.Deserialize<NflRoster>("""{"season":2005,"teamId":"A","playerId":"p1","name":"Legacy","position":"QB","jerseyNumber":"12","status":"ACT"}""", new JsonSerializerOptions(JsonSerializerDefaults.Web));
Check(legacyRoster?.JerseyNumber==12,"Historical numeric-string jersey number reads correctly");
Console.WriteLine($"All {checks} calculator checks passed.");
